package com.badrulamin.University_Management.service;   import com.badrulamin.University_Management.entity.Faculty; import com.badrulamin.University_Management.entity.FacultyName; import com.badrulamin.University_Management.repository.FacultyNameRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service;  import java.util.List; import java.util.Optional;  @Service @RequiredArgsConstructor public class FacultyNameServiceImp implements  FacultyNameService{       private final FacultyNameRepository fcacultyNameRepository;      @Override     public FacultyName save(FacultyName facultyName) {         return fcacultyNameRepository.save(facultyName);     }      @Override     public FacultyName update(Long id, FacultyName faculty) {          FacultyName existing = fcacultyNameRepository.findById(id)                 .orElseThrow(() -> new RuntimeException("Faculty not found"));          existing.setFacultyName(faculty.getFacultyName());         existing.setDescription(faculty.getDescription());         existing.setActive(faculty.getActive());          return fcacultyNameRepository.save(existing);     }      @Override     public List<FacultyName> findAll() {         return fcacultyNameRepository.findAll();     }      @Override     public Optional<FacultyName> findById(Long id) {         return fcacultyNameRepository.findById(id);     }      @Override     public void delete(Long id) {         fcacultyNameRepository.deleteById(id);     }      @Override     public boolean existsById(Long id) {         return fcacultyNameRepository.existsById(id);     } }